-- The Noro Psychic O.C.C., Rifts Dimension Book 2: Phase World p.63-64.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-noro-psychic-class.sql
--
-- Generated by scripts/class-check.mjs --emit-script from a validated draft.
-- Apostrophes are doubled and non-ASCII is spliced with char(); CR is stripped.
-- Run class-check on THIS file before applying - the ASCII/CRLF pre-flight only
-- fires against the real artifact.


-- The class itself. INSERT ... WHERE NOT EXISTS rather than INSERT OR IGNORE,
-- so re-running the script is a no-op instead of a silent partial write.
INSERT INTO imported_classes (class_id, name, system, markdown, status, created_by)
SELECT 'noro-psychic', 'Noro Psychic', 'rifts', '---
id: noro-psychic
name: Noro Psychic
system: rifts
category: occ
occ_group: psychic
source_book: Rifts Dimension Book 2: Phase World p.63-64
attribute_requirements: { ME: 14 }
starting_money: "4d6x1000"
xp_table: [0, 2601, 5001, 10001, 20001, 30001, 39001, 52001, 70001, 100001, 140001, 190001, 240001, 290001, 350001]
